// ============================================================
// DEMO SEED v1.1: Write directly to canonical fields
// ============================================================
// HubSpot native email fields (hs_email_open, hs_email_click,
// hs_email_sends_since_last_engagement) are READ ONLY.
// This seed writes to our own canon_ fields instead.
//
// The engagement-check report reads from canon_ fields,
// so the demo story is identical.
//
// Distribution across 20 contacts:
//   Active   (score 75-95):  6 contacts
//   At Risk  (score 45-60):  5 contacts
//   Cold     (score 25-40):  5 contacts
//   Dormant  (score 5-20):   4 contacts
// ============================================================

const response = $input.first().json;
const contacts = response.results || [];

if (contacts.length === 0) {
  throw new Error('No contacts found. Check HubSpot connection.');
}

const now = new Date().toISOString();

// ---- Seed profiles — written to canon_ fields ----
const seedProfiles = [
  // Active — healthy engagement
  { status: 'Active',  score: 95, daysSince: 2  },
  { status: 'Active',  score: 88, daysSince: 5  },
  { status: 'Active',  score: 82, daysSince: 8  },
  { status: 'Active',  score: 91, daysSince: 1  },
  { status: 'Active',  score: 76, daysSince: 12 },
  { status: 'Active',  score: 85, daysSince: 4  },

  // At Risk — starting to go quiet
  { status: 'At Risk', score: 58, daysSince: 28  },
  { status: 'At Risk', score: 52, daysSince: 35  },
  { status: 'At Risk', score: 61, daysSince: 22  },
  { status: 'At Risk', score: 47, daysSince: 42  },
  { status: 'At Risk', score: 55, daysSince: 30  },

  // Cold — clear non-engagement pattern
  { status: 'Cold',    score: 38, daysSince: 65  },
  { status: 'Cold',    score: 29, daysSince: 80  },
  { status: 'Cold',    score: 33, daysSince: 72  },
  { status: 'Cold',    score: 25, daysSince: 90  },
  { status: 'Cold',    score: 41, daysSince: 58  },

  // Dormant — essentially unresponsive
  { status: 'Dormant', score: 18, daysSince: 145 },
  { status: 'Dormant', score: 8,  daysSince: 210 },
  { status: 'Dormant', score: 12, daysSince: 180 },
  { status: 'Dormant', score: 5,  daysSince: 290 }
];

// ---- Map each contact to a seed profile ----
const updates = contacts.map((contact, index) => {
  const profile = seedProfiles[index % seedProfiles.length];
  const name = [contact.properties?.firstname, contact.properties?.lastname]
    .filter(Boolean).join(' ') || contact.properties?.email || `Contact ${contact.id}`;

  return {
    contactId:   contact.id,
    contactName: name,
    profile,
    // These are all writable canonical fields we own
    properties: {
      canon_engagement_score:            String(profile.score),
      canon_engagement_status:           profile.status,
      canon_days_since_engagement:       String(profile.daysSince),
      canon_engagement_last_calculated:  now
    }
  };
});

// Log distribution for verification
const dist = updates.reduce((acc, u) => {
  acc[u.profile.status] = (acc[u.profile.status] || 0) + 1;
  return acc;
}, {});
console.log(`[SEED v1.1] Seeding ${updates.length} contacts:`, JSON.stringify(dist));

return updates.map(u => ({ json: u }));

// Grab the contact name/profile from Assign Seed Profiles
// (current item in the loop)
const allItems = $('Assign Seed Profiles').all();
const loopIndex = $('Process Each Contact').context.currentRunIndex;
const current = allItems[loopIndex]?.json;

if (current) {
  console.log(`[SEED] ✓ ${current.contactName} → ${current.profile.status} (score: ${current.profile.score}, days: ${current.profile.daysSince})`);
}

return [{ json: { seeded: true, contactId: current?.contactId } }];

console.log('[SEED] ✅ All contacts seeded. Run /engagement-check in Slack.');
return [{
  json: {
    status:    'complete',
    message:   'Demo data seeded successfully. Run /engagement-check in Slack.',
    timestamp: new Date().toISOString()
  }
}];
